const search1 = $('Search the main topic').item.json;
const search2 = $input.first().json;
const cfg = $('Set config').item.json;

// Parse main topic results (top 8)
const results1 = (search1.organic || []).slice(0, 8).map((r, i) => ({
  sourceNum: i + 1,
  title: r.title || 'No title',
  url: r.link || '',
  snippet: r.snippet || '',
  date: r.date || '',
  angle: 'Main topic'
}));

// Parse expert angle results (top 7, deduplicate URLs)
const existingUrls = results1.map(r => r.url);
const results2 = (search2.organic || [])
  .filter(r => !existingUrls.includes(r.link || ''))
  .slice(0, 7)
  .map((r, i) => ({
    sourceNum: results1.length + i + 1,
    title: r.title || 'No title',
    url: r.link || '',
    snippet: r.snippet || '',
    date: r.date || '',
    angle: 'Expert angle'
  }));

const allResults = [...results1, ...results2];

// Format for AI — structured numbered source list
const researchContent = allResults.map(r =>
  '[Source ' + r.sourceNum + '] ' + r.title + '\n' +
  'URL: ' + r.url + '\n' +
  (r.date ? 'Date: ' + r.date + '\n' : '') +
  'Summary: ' + r.snippet
).join('\n\n');

// Clean source list for the email
const sourceList = allResults.map(r =>
  r.sourceNum + '. ' + r.title + '\n   ' + r.url
).join('\n\n');

return [{
  json: {
    researchContent,
    sourceList,
    sourceCount: allResults.length,
    mainTopic: cfg.mainTopic,
    targetAudience: cfg.targetAudience,
    reportGoal: cfg.reportGoal,
    specificAngle: cfg.specificAngle,
    requestedBy: cfg.requestedBy,
    recipientEmail: cfg.recipientEmail,
    senderName: cfg.senderName,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName,
    today: cfg.today
  }
}];

parameters.text:
=You are a professional research report writer who creates clear, authoritative reports for business audiences.

Topic: {{ $json.mainTopic }}
Audience: {{ $json.targetAudience }}
Goal: {{ $json.reportGoal }}
Sources analyzed: {{ $json.sourceCount }}

Research intelligence extracted:
Key findings: {{ $json.keyFindings.join(' | ') }}
Data points: {{ $json.dataPoints.join(' | ') }}
Expert positions: {{ $json.expertPositions.join(' | ') }}
Knowledge gaps: {{ $json.knowledgeGaps.join(' | ') }}
Contradictions: {{ $json.contradictions.join(' | ') || 'None identified' }}
Research confidence: {{ $json.researchConfidence }} out of 10

Write a complete professional research report. Return ONLY a valid JSON object. No extra text. No markdown. No backticks.

Required fields:

reportTitle
A clear, specific title for this research report. Under 12 words.

executiveSummary
3 to 4 sentences. What was found, why it matters to the target audience, and the single most important conclusion. Plain text.

background
1 to 2 paragraphs. Why this topic is relevant right now and what context the reader needs. Plain text.

keyInsights
Array of exactly 5 strings. The most important insights from the research, written as clear standalone statements. Each under 40 words.

detailedFindings
3 to 4 paragraphs. The substance of what the research found. Reference specific evidence and data points. Plain text.

implications
2 paragraphs. What these findings mean specifically for the target audience. Be direct about business and strategic implications. Plain text.

recommendedActions
Array of exactly 4 strings. Specific, actionable steps the target audience should take based on these findings. Each under 30 words.

conclusion
2 to 3 sentences. Wrap up the report and state the most important thing to remember. Plain text.
